// Solutions of the IMO papers, one dedicated page each (#olympiad/imo/<year>-<n>/solution). The 2025 solutions follow the
// official IMO 2025 shortlist (problem 1 = C1, 2 = G4, 3 = N7, 4 = N3, 5 = A3, 6 = C8), condensed and reworded; the French
// text is a translation of that wording, to be reviewed. 2026 has no solution here: no official source was supplied.
// An entry is { from, answer, body }: `from` the shortlist label, `answer` a pair, `body` paragraphs (pairs); a paragraph
// starting with "§" is a short heading. Maths between \( \) for MathJax.
const P = (fr, en) => [fr, en];
const H = (fr, en) => P('§' + fr, '§' + en);

